// Screen 05 round 8: the lead's motion_audit (tools/lead_r6/motion_audit.mjs) with a shot filter + per-shot probes
// (coin screen sizes, Benny's screen box). Same shot list / same simulation stepping as the audit, so a shot taken here
// equals the audit frame of the same name. Run from the checkout:
//   node tools/match05/r8_shots.mjs <outDir> "<query>" [name,name,...|all] [port]
import { mkdirSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
const { loadPlaywright, CHROMIUM_ARGS } = await import(pathToFileURL(`${process.cwd()}/scripts/lib/pw.mjs`).href);
import { realpathSync, mkdirSync as mk, rmSync, readFileSync } from 'node:fs';
// own dev server: node_modules is a symlink into the lead checkout in this worktree, so Vite's default fs allow list
// refused the HUD font (fallback font in the HUD). Same render-slot protocol as scripts/lib/pw.mjs.
async function startVite(port) {
  const slots = Math.max(1, Number(process.env.RAINBOW_RENDER_SLOTS ?? 2));
  const alive = (pid) => { try { process.kill(pid, 0); return true; } catch { return false; } };
  let free = () => {};
  const t0 = Date.now();
  outer: for (;;) {
    for (let i = 0; i < slots; i++) {
      const dir = `/tmp/rainbow-render-slot-${i}`;
      try { mk(dir); writeFileSync(`${dir}/pid`, String(process.pid)); free = () => { try { rmSync(dir, { recursive: true, force: true }); } catch { /* */ } }; process.on('exit', free); break outer; } catch {
        let pid = NaN; try { pid = Number(readFileSync(`${dir}/pid`, 'utf8')); } catch { /* */ }
        if (Number.isFinite(pid) && !alive(pid)) { try { rmSync(dir, { recursive: true, force: true }); } catch { /* */ } }
      }
    }
    if (Date.now() - t0 > 40 * 60 * 1000) break;
    await new Promise((r) => setTimeout(r, 1500));
  }
  const { createServer } = await import('vite');
  const server = await createServer({ server: { port, strictPort: false, host: '127.0.0.1', hmr: false, watch: { ignored: ['**/*'] }, fs: { allow: [process.cwd(), realpathSync(`${process.cwd()}/node_modules`)] } }, logLevel: 'error' });
  await server.listen();
  const addr = server.resolvedUrls?.local?.[0] ?? `http://127.0.0.1:${port}/`;
  return { url: addr.replace(/\/$/, ''), close: async () => { try { await server.close(); } finally { free(); } } };
}
const [OUT, Q = '', ONLY = 'all', PORT = '5291'] = process.argv.slice(2);
mkdirSync(OUT, { recursive: true });
const { chromium } = loadPlaywright();
const vite = await startVite(Number(PORT));
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
const log = [];
const ALL = [
  ['a00_approved_view', 0, null],
  ['f03_forward3u', 3, null], ['f06_forward6u', 6, null], ['f10_forward10u', 10, null], ['f20_forward20u', 20, null],
  ['s_left_steer', 6, -1], ['s_right_steer', 6, 1], ['s_left_hard', 12, -1], ['s_right_hard', 12, 1],
  ['t33_through_screen', 't0.33', null], ['t66_through_screen', 't0.66', null], ['t95_through_screen', 't0.95', null],
];
// round 11: extra probe positions, only when named (not part of 'all' = the 12 audit shots)
const EXTRA = [
  ['k81_kink', 't0.81', null], ['k81_kink_left', 't0.81', -1], ['k81_kink_right', 't0.81', 1],
  ['t75_through', 't0.75', null], ['t85_through', 't0.85', null], ['t90_through', 't0.90', null],
];
const want = ONLY === 'all' ? null : new Set(ONLY.split(','));
const SHOTS = want ? [...ALL, ...EXTRA].filter(([n]) => want.has(n)) : ALL;
try {
  const page = await browser.newPage({ viewport: { width: 864, height: 1536 }, deviceScaleFactor: 1 });
  page.on('pageerror', (e) => console.error('pageerror', e.message));
  page.on('console', (m) => { if (m.type() === 'error') console.error('console', m.text()); });
  await page.goto(`${vite.url}/?qa=1&dpr=1${Q ? '&' + Q : ''}`);
  await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 300000 });
  for (const [name, dist, steer] of SHOTS) {
    const st = await page.evaluate(async ([id, dist, steer]) => {
      const r = window.__rainbow; r.goto(id);
      const s0 = r.state().s;
      const stg = r.course.stage(id);
      const s1 = stg.s1 ?? (stg.s0 + (stg.length ?? 0));
      const target = typeof dist === 'string' ? s0 + Number(dist.slice(1)) * Math.max(0, s1 - s0) : s0 + dist;
      r.setSteer(steer);
      let n = 0; while (r.state().s < target - 1e-3 && n < 4000) { r.step(1); n++; }
      r.setSteer(null);
      r.run(true); await new Promise((res) => requestAnimationFrame(() => requestAnimationFrame(res))); r.run(false);
      return { ...r.state(), frames: n, s0, s1, target, coinsOnScreen: r.coinScreen(), benny: r.bennyScreen() };
    }, ['05', dist, steer]);
    await page.waitForTimeout(150);
    await page.screenshot({ path: `${OUT}/${name}.png` });
    log.push({ name, dist, steer, ...st });
    const big = st.coinsOnScreen.filter((c) => c.d > 60).map((c) => `#${c.i}@${c.x},${c.y} d${c.d}`).join(' ');
    console.log(name, 's', st.s, 'lat', st.lat, 'coins', st.coins, 'benny', st.benny.x, st.benny.y, 'big coins:', big || '-');
  }
} finally {
  writeFileSync(`${OUT}/shots.json`, JSON.stringify({ query: Q, shots: log }, null, 1));
  await browser.close(); await vite.close?.();
}

/**
 * `?match05=1&m05far=1` — Screen 05 round 7 (line B, qa/match/05/NOTES.md "Round 7"): the far forced-perspective tunnel
 * of Screen 05 (environment.ts `// ---- 05 far tunnel`, tube.ts ForcedTunnel) recalibrated to the LIVE camera every
 * frame instead of folding away.
 *
 * Why: the far block (rings C … G, the far S-river, the warm throat) is a depth compression along the eye rays of the
 * LOCKED checkpoint eye. From ≈34 u before its seam (sF05) it folded away (`openFor`), so from ≈20 u into the stage the
 * camera saw the far rings / river morphing out and the 06 arch hall behind them — the "old pink default world" of
 * the lead's audit (t66 / t95 frames). The compression is exact for ANY eye position once its two eye-dependent
 * constants (D0 = eye depth of the seam, q = eye offset from the axis) follow the eye, so under this switch:
 *   * the VIRTUAL tunnel (virtual depth Z beyond sF05, tunnel coordinate v = sF05 + u(Z)) stays put — rings, wall rows,
 *     the baked far water F and the far river layout are anchored to it, so everything approaches like real geometry;
 *   * the seam slides ahead of the eye so it never comes nearer than the locked view had it (D0lock ≈ 53 u): the part
 *     of the virtual tunnel between sF05 and the seam is drawn at REAL scale (k = 1) on the same straight axis (it
 *     covers the 05 → 06 flare), capped at `zCap` (just past the 06 start: the 06 river must not climb inside it);
 *   * the far river starts AT the seam (the real ribbon carries the course, coins and Benny before it);
 *   * only at the very end of the stage (eye ≤ ~11 u from the capped seam) the block folds away as before, into 06.
 * Default build and `?match05=1` without `m05far`: this file is never called (environment.ts keeps `openFor`).
 */
import * as THREE from 'three';
import type { ForcedTunnel, TubeWarp } from './tube';
import { tubeCenterAt } from './tube';
import type { FarRiverLayout, FarRiverRow } from './far05';
import type { Course, CourseSample } from './course';
import { EDGE_LIFT, M05BLEND, MATCH05, ampAt, flag05, m05blend, m05blendTime, m05eye, m05seam } from '../vfx/waterRibbon';
import { clip05 } from '../vfx/clip05';

export const M05FAR: boolean = MATCH05 && flag05('m05far');

type Item = { u: number; o: THREE.Vector3; basis: THREE.Matrix4; s: THREE.Vector3; openPos: THREE.Vector3; openScale: number };

export interface LiveFar05Args {
  ft: ForcedTunnel;
  farWall: THREE.Mesh;
  farRiver: THREE.Mesh;
  farRings: THREE.InstancedMesh;
  farLids: THREE.InstancedMesh;
  ringItems: Item[];
  lidItems: Item[];
  glow: THREE.Mesh;
  glowMat: THREE.ShaderMaterial;
  lay: FarRiverLayout;
  level: number;
  zEnd: number;
  warp?: TubeWarp;
  /** wall build parameters (as ft.geometry(radial, steps, inset)) */
  radial: number; wallSteps: number; inset: number;
  /** river build parameters (as farRiverGeometry(cols, steps)) */
  cols: number; riverSteps: number;
  /** largest real extension beyond sF05 (units) */
  zCap: number;
  /** fold window: eye → seam distance (units) */
  foldNear: number; foldFar: number;
  /** the real course's height above the axis at real distance z beyond sF05 (the far water meets it at the seam) */
  riverUp: (z: number) => number;
  /** `&m05blend=1` (round 9): the real course (the far river's first rows are laid onto the ribbon's surface at the seam) */
  course?: Course;
}

const ROW_KEYS: (keyof FarRiverRow)[] = ['xB', 'hw', 'cL', 'wL', 'cR', 'wR', 'core'];

/** returns sync(cam): call from every far part's onBeforeRender */
export function createLiveFar05(a: LiveFar05Args): (cam: THREE.Camera) => void {
  const { ft } = a;
  const L = ft.L, c0 = ft.c0, T = ft.T, U = ft.U, Rt = ft.Rt, R = ft.R, sF = ft.sF;
  const D0lock = ft.D0;
